-- 547: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 9 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_547_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_547_guard;
INSERT INTO _migration_547_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_041' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality x + 5 > 9 for x.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x > 4","B. x > 14","C. x < 4","D. x > 5"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Subtract 5 from both sides: x > 9 − 5, so x > 4. Check: 4 + 5 = 9, so any value above 4 works. (x > 14 adds 5 instead of subtracting; x < 4 reverses the sign for no reason.) Therefore the correct answer is A: x > 4.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_041' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_547_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_042' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality 2x ≤ 10.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x ≥ 5","B. x ≤ 5","C. x ≤ 8","D. x < 5"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Divide both sides by the positive number 2, keeping the sign: x ≤ 5. (x < 5 drops the equality, excluding x = 5 which satisfies 2(5) = 10 ≤ 10.) Therefore the correct answer is B: x ≤ 5.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_042' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_547_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_043' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following values satisfies the inequality x − 2 < 5?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 7","B. x = 8","C. x = 6","D. x = 9"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Substituting x = 6 gives 6 − 2 = 4, and 4 < 5, so x = 6 satisfies the inequality. The other values give 5, 6 and 7, none of which is less than 5. Equivalently, solving gives x < 7, and only 6 qualifies. Therefore the correct answer is C: x = 6.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_043' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_547_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_044' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality 3x > 12.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x < 4","B. x > 36","C. x > 9","D. x > 4"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Divide both sides by the positive number 3: x > 4. Check: 3 × 4 = 12, so values above 4 work. (x > 36 multiplies by 3 instead of dividing; x > 9 subtracts 3.) Therefore the correct answer is D: x > 4.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_044' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_547_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_045' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality 3x − 4 ≤ 11.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x ≤ 5","B. x ≤ 7/3","C. x < 5","D. x ≥ 5"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Add 4 to both sides: 3x ≤ 15. Divide by the positive number 3: x ≤ 5. Check: 3(5) − 4 = 11, and 11 ≤ 11 holds. (x ≤ 7/3 subtracts 4 from 11 instead of adding.) Therefore the correct answer is A: x ≤ 5.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_045' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_041', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the inequality x + 5 > 9 for x.', 'multiple_choice', NULL, '["A. x > 4","B. x > 14","C. x < 4","D. x > 5"]', 'A', 'Subtract 5 from both sides: x > 9 − 5, so x > 4. Check: 4 + 5 = 9, so any value above 4 works. (x > 14 adds 5 instead of subtracting; x < 4 reverses the sign for no reason.) Therefore the correct answer is A: x > 4.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO1', NULL, NULL, 'board_waec');
