INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_043', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Which of the following values satisfies the inequality x − 2 < 5?', 'multiple_choice', NULL, '["A. x = 7","B. x = 8","C. x = 6","D. x = 9"]', 'C', 'Substituting x = 6 gives 6 − 2 = 4, and 4 < 5, so x = 6 satisfies the inequality. The other values give 5, 6 and 7, none of which is less than 5. Equivalently, solving gives x < 7, and only 6 qualifies. Therefore the correct answer is C: x = 6.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_044', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the inequality 3x > 12.', 'multiple_choice', NULL, '["A. x < 4","B. x > 36","C. x > 9","D. x > 4"]', 'D', 'Divide both sides by the positive number 3: x > 4. Check: 3 × 4 = 12, so values above 4 work. (x > 36 multiplies by 3 instead of dividing; x > 9 subtracts 3.) Therefore the correct answer is D: x > 4.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_045', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the inequality 3x − 4 ≤ 11.', 'multiple_choice', NULL, '["A. x ≤ 5","B. x ≤ 7/3","C. x < 5","D. x ≥ 5"]', 'A', 'Add 4 to both sides: 3x ≤ 15. Divide by the positive number 3: x ≤ 5. Check: 3(5) − 4 = 11, and 11 ≤ 11 holds. (x ≤ 7/3 subtracts 4 from 11 instead of adding.) Therefore the correct answer is A: x ≤ 5.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
